[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<script src="https://cdn.tailwindcss.com"></script>
<script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root {
    --brand-blue: #3861FB;
    --navy: #0D1421;
    --gray: #808A9D;
    --green: #16c784;
    --red: #ea3943;
    --bg: #ffffff;
    --bg-secondary: #f8fafc;
    --border: #e2e8f0;
    --text-primary: #0D1421;
    --text-secondary: #808A9D;
    --text-muted: #94a3b8;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg-secondary);
    color: var(--text-primary);
    -webkit-font-smoothing: antialiased;
  }
  .font-tabular { font-variant-numeric: tabular-nums; }

  /* Top Bar */
  .top-bar {
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    padding: 8px 0;
  }
  .top-bar .stat-value { font-size: 14px; font-weight: 600; color: var(--navy); }
  .top-bar .stat-label { font-size: 11px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; }
  .top-bar .stat-change.positive { color: var(--green); }
  .top-bar .stat-change.negative { color: var(--red); }

  /* Nav */
  .main-nav {
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    z-index: 50;
  }
  .nav-link {
    font-size: 14px;
    font-weight: 500;
    color: var(--text-secondary);
    padding: 12px 16px;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    transition: all 150ms ease;
  }
  .nav-link:hover, .nav-link.active { color: var(--navy); border-bottom-color: var(--brand-blue); }

  /* Network Tabs */
  .network-tab {
    font-size: 13px;
    font-weight: 500;
    padding: 6px 14px;
    border-radius: 8px;
    cursor: pointer;
    transition: all 150ms ease;
    color: var(--text-secondary);
    background: transparent;
    border: 1px solid var(--border);
    white-space: nowrap;
  }
  .network-tab:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
  .network-tab.active { background: var(--brand-blue); color: white; border-color: var(--brand-blue); }

  /* Category Tabs */
  .category-tab {
    font-size: 13px;
    font-weight: 500;
    padding: 6px 16px;
    border-radius: 8px;
    cursor: pointer;
    transition: all 150ms ease;
    color: var(--text-secondary);
    background: transparent;
    border: none;
    white-space: nowrap;
  }
  .category-tab:hover { color: var(--navy); background: var(--bg-secondary); }
  .category-tab.active { background: var(--bg-secondary); color: var(--navy); font-weight: 600; }

  /* Promo Banner */
  .promo-banner {
    background: linear-gradient(135deg, #3861FB 0%, #5B3CC4 100%);
    color: white;
    padding: 12px 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    overflow: hidden;
    position: relative;
  }
  .promo-slide {
    display: none;
    align-items: center;
    gap: 12px;
    flex: 1;
    animation: slideIn 400ms ease-out;
  }
  .promo-slide.active { display: flex; }
  @keyframes slideIn {
    from { opacity: 0; transform: translateX(20px); }
    to { opacity: 1; transform: translateX(0); }
  }

  /* AI Bar */
  .ai-bar {
    background: #f0f4ff;
    border-bottom: 1px solid #dde4f9;
    padding: 10px 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    overflow-x: auto;
  }
  .ai-suggestion {
    font-size: 12px;
    color: var(--brand-blue);
    background: white;
    border: 1px solid #dde4f9;
    border-radius: 20px;
    padding: 6px 14px;
    cursor: pointer;
    white-space: nowrap;
    transition: all 150ms ease;
  }
  .ai-suggestion:hover { background: var(--brand-blue); color: white; border-color: var(--brand-blue); }

  /* Table Styles */
  .crypto-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 13px;
  }
  .crypto-table thead { position: sticky; top: 100px; z-index: 10; }
  .crypto-table th {
    background: #f8fafc;
    color: var(--text-secondary);
    font-weight: 600;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
  }
  .crypto-table th:hover { color: var(--navy); }
  .crypto-table th.sort-asc::after { content: ' ▴'; color: var(--brand-blue); }
  .crypto-table th.sort-desc::after { content: ' ▾'; color: var(--brand-blue); }
  .crypto-table td {
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
    white-space: nowrap;
  }
  .crypto-table tbody tr { transition: background 100ms ease; }
  .crypto-table tbody tr:hover { background: #f8fafc; }
  .crypto-table .rank { color: var(--text-muted); font-weight: 500; font-size: 12px; }
  .crypto-table .name-col { display: flex; align-items: center; gap: 8px; }
  .crypto-table .crypto-icon {
    width: 28px; height: 28px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 10px; color: white; flex-shrink: 0;
  }
  .crypto-table .crypto-name { font-weight: 600; color: var(--navy); }
  .crypto-table .crypto-symbol { font-size: 11px; color: var(--text-muted); }
  .crypto-table .price { font-weight: 600; font-variant-numeric: tabular-nums; }
  .crypto-table .change { font-weight: 500; font-variant-numeric: tabular-nums; }
  .crypto-table .change.positive { color: var(--green); }
  .crypto-table .change.negative { color: var(--red); }
  .crypto-table .numeric { text-align: right; font-variant-numeric: tabular-nums; }
  .crypto-table .sparkline svg { width: 110px; height: 32px; }

  /* Index Row */
  .index-row td {
    background: #f8fafc;
    font-weight: 500;
    padding: 12px;
    border-bottom: 2px solid var(--border);
  }

  /* Controls Bar */
  .table-controls {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 0;
    flex-wrap: wrap;
  }
  .control-btn {
    font-size: 13px;
    font-weight: 500;
    padding: 7px 14px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: var(--bg);
    color: var(--text-secondary);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    transition: all 150ms ease;
  }
  .control-btn:hover, .control-btn.active { border-color: var(--brand-blue); color: var(--brand-blue); }
  .control-btn .sort-arrow { font-size: 10px; }

  /* Pagination */
  .pagination-btn {
    width: 36px; height: 36px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 8px;
    font-size: 13px; font-weight: 500;
    cursor: pointer;
    border: 1px solid var(--border);
    background: var(--bg);
    color: var(--text-secondary);
    transition: all 150ms ease;
  }
  .pagination-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
  .pagination-btn.active { background: var(--brand-blue); color: white; border-color: var(--brand-blue); }

  /* Columns Panel */
  .columns-panel {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    background: white;
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.1);
    padding: 16px;
    z-index: 30;
    min-width: 200px;
  }
  .columns-panel.show { display: block; }
  .columns-panel label {
    display: flex; align-items: center; gap: 8px;
    font-size: 13px; color: var(--text-primary);
    padding: 6px 0; cursor: pointer;
  }
  .columns-panel input[type="checkbox"] { accent-color: var(--brand-blue); }

  /* Filter Panel */
  .filter-panel {
    display: none;
    background: white;
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.1);
    padding: 20px;
    margin-top: 8px;
  }
  .filter-panel.show { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
  .filter-group label { font-size: 11px; font-weight: 600; text-transform: uppercase; color: var(--text-secondary); display: block; margin-bottom: 6px; letter-spacing: 0.5px; }
  .filter-group select, .filter-group input {
    width: 100%; padding: 8px 12px; border: 1px solid var(--border); border-radius: 8px;
    font-size: 13px; font-family: inherit;
  }

  /* Market Summary */
  .summary-more { display: none; }
  .summary-more.show { display: block; }

  /* Info Content */
  .info-card {
    background: white;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
  }

  /* Footer */
  .footer { background: var(--navy); color: white; }
  .footer a { color: var(--text-muted); text-decoration: none; font-size: 13px; transition: color 150ms; }
  .footer a:hover { color: white; }
  .footer h4 { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 12px; color: white; }

  /* Scrollbar */
  ::-webkit-scrollbar { height: 6px; width: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }

  /* Cookie / bottom banner */
  .bottom-banner {
    position: fixed; bottom: 16px; left: 50%; transform: translateX(-50%);
    background: var(--navy); color: white; padding: 12px 24px; border-radius: 12px;
    font-size: 13px; display: flex; align-items: center; gap: 16px;
    z-index: 100; box-shadow: 0 8px 30px rgba(0,0,0,0.2);
  }

  @media (max-width: 768px) {
    .crypto-table .col-1h, .crypto-table .col-supply, .crypto-table .col-sparkline { display: none; }
    .top-bar { overflow-x: auto; }
  }
</style>
</head>
<body>

