}

function sparklineSVG(data, trend) {
  const w = 110, h = 32, pad = 2;
  const min = Math.min(...data), max = Math.max(...data), range = max - min || 1;
  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * (w - 2 * pad);
    const y = pad + (1 - (v - min) / range) * (h - 2 * pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const color = trend >= 0 ? '#16c784' : '#ea3943';
  const lastX = pad + (w - 2 * pad), lastY = pad + (1 - (data[data.length-1] - min) / range) * (h - 2 * pad);
  return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${lastX.toFixed(1)}" cy="${lastY.toFixed(1)}" r="2" fill="${color}"/></svg>`;
}

function formatPrice(v) {
  if (v >= 1000) return '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  if (v >= 1) return '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  if (v >= 0.01) return '$' + v.toFixed(4);
  return '$' + v.toFixed(8);
}

function formatMcap(v) {
  if (v >= 1e12) return '$' + (v / 1e12).toFixed(2) + 'T';
  if (v >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v / 1e6).toFixed(0) + 'M';
  return '$' + v.toFixed(0);
}

function formatVol(v) {
  const n = parseFloat(v);
  if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n / 1e6).toFixed(0) + 'M';
  return '$' + n.toFixed(2);
}

// Pre-compute all data
const allCryptos = cryptoNames.map((c, i) => {
  const price = i < 100 ? parseFloat(genPrice(i)) : parseFloat((Math.random() * 100 + 1).toFixed(4));
  const change1h = genChange();
  const change24h = genChange();
  const change7d = genChange();
  const marketCap = genMcap(i, price);
  const volume = genVolume(i);
  const supply = genSupply(i, c.sym);
  const spark = sparklineData(30);
  return {
    rank: i + 1,
    name: c.name,
    symbol: c.sym,
    price,
    change1h,
    change24h,
    change7d,
    marketCap,
    volume,
    supply,
    network: c.network,
    category: c.cat,
    sparkData: spark,
    color: colors[i % colors.length]
  };
});

// State
let currentPage = 1;
const rowsPerPage = 100;
let currentCategory = 'top';
let currentNetwork = 'all';
let sortField = 'rank';
let sortDir = 'asc';
let filters = { priceMin: null, priceMax: null, marketCapMin: null, change24h: null };

function getFilteredData() {
  let data = [...allCryptos];

  // Network filter
  if (currentNetwork !== 'all') {
    data = data.filter(c => c.network === currentNetwork);
  }

  // Category filter
  if (currentCategory !== 'all') {
    if (currentCategory === 'trending') data = data.filter(c => c.category === 'trending');
    else if (currentCategory === 'watchlist') data = data.filter(c => c.rank <= 20);
    else if (currentCategory === 'prediction') data = data.filter(c => c.category === 'prediction');
    else if (currentCategory === 'visited') data = data.slice(0, 50);
    else if (currentCategory === 'new') data = data.filter(c => c.category === 'new');
    else if (currentCategory === 'top') data = data.filter(c => c.category === 'top');
  }

  // Filters
  if (filters.priceMin) data = data.filter(c => c.price >= filters.priceMin);
  if (filters.priceMax) data = data.filter(c => c.price <= filters.priceMax);
  if (filters.marketCapMin === '1b') data = data.filter(c => c.marketCap >= 1e9);
  if (filters.marketCapMin === '10b') data = data.filter(c => c.marketCap >= 10e9);
  if (filters.marketCapMin === '100b') data = data.filter(c => c.marketCap >= 100e9);
  if (filters.change24h === 'positive') data = data.filter(c => c.change24h > 0);
  if (filters.change24h === 'negative') data = data.filter(c => c.change24h < 0);
  if (filters.change24h === '5+') data = data.filter(c => c.change24h >= 5);
  if (filters.change24h === '5-') data = data.filter(c => c.change24h <= -5);

  return data;
}

function sortData(data) {
  return data.sort((a, b) => {
    let va, vb;
    switch (sortField) {
      case 'rank': va = a.rank; vb = b.rank; break;
      case 'price': va = a.price; vb = b.price; break;
      case 'change1h': va = a.change1h; vb = b.change1h; break;
      case 'change24h': va = a.change24h; vb = b.change24h; break;
      case 'change7d': va = a.change7d; vb = b.change7d; break;
      case 'marketCap': va = a.marketCap; vb = b.marketCap; break;
      case 'volume': va = parseFloat(a.volume); vb = parseFloat(b.volume); break;
      case 'supply': va = a.rank; vb = b.rank; break;
      default: va = a.rank; vb = b.rank;
    }
    return sortDir === 'asc' ? va - vb : vb - va;
  });
}

function renderTable() {
  let data = getFilteredData();
  data = sortData(data);

  const totalPages = Math.ceil(data.length / rowsPerPage);
  if (currentPage > totalPages) currentPage = totalPages || 1;
  const start = (currentPage - 1) * rowsPerPage;
  const pageData = data.slice(start, start + rowsPerPage);

  // Index row
  let html = `<tr class="index-row">
    <td class="col-rank" style="text-align:center;">◆</td>
    <td class="col-name"><div class="name-col"><div class="crypto-icon" style="background:var(--brand-blue);">CT</div><div><div class="crypto-name">CoinTracker 20 Index</div><div class="crypto-symbol">DTFCTP20</div></div></div></td>
    <td class="col-price numeric price">$154.29</td>
    <td class="col-1h numeric change positive">+0.21%</td>
    <td class="col-24h numeric change positive">+1.15%</td>
    <td class="col-7d numeric change positive">+4.97%</td>
    <td class="col-mcap numeric">--</td>
    <td class="col-volume numeric">--</td>
    <td class="col-supply numeric">--</td>
    <td class="col-sparkline" style="text-align:right;">${sparklineSVG(sparklineData(30), 4.97)}</td>
  </tr>`;

  pageData.forEach((c, idx) => {
    const ch1 = c.change1h >= 0;
    const ch24 = c.change24h >= 0;
    const ch7d = c.change7d >= 0;
    const spark = sparklineSVG(c.sparkData, c.change7d);
    const iconBg = c.color;

    html += `<tr data-network="${c.network}" data-category="${c.category}">
      <td class="col-rank" style="text-align:center;"><span class="rank">${start + idx + 1}</span></td>
      <td class="col-name"><div class="name-col"><div class="crypto-icon" style="background:${iconBg};font-size:10px;">${c.symbol.slice(0,2)}</div><div><div class="crypto-name">${c.name}</div><div class="crypto-symbol">${c.symbol}</div></div></div></td>
      <td class="col-price numeric price">${formatPrice(c.price)}</td>
      <td class="col-1h numeric change ${ch1 ? 'positive' : 'negative'}">${ch1 ? '+' : ''}${c.change1h.toFixed(2)}%</td>
      <td class="col-24h numeric change ${ch24 ? 'positive' : 'negative'}">${ch24 ? '+' : ''}${c.change24h.toFixed(2)}%</td>
      <td class="col-7d numeric change ${ch7d ? 'positive' : 'negative'}">${ch7d ? '+' : ''}${c.change7d.toFixed(2)}%</td>
      <td class="col-mcap numeric">${formatMcap(c.marketCap)}</td>
      <td class="col-volume numeric">${formatVol(c.volume)}</td>
      <td class="col-supply numeric">${c.supply} ${c.symbol}</td>
      <td class="col-sparkline" style="text-align:right;">${spark}</td>
    </tr>`;
  });

  document.getElementById('tableBody').innerHTML = html;
  document.getElementById('showingStart').textContent = start + 1;
  document.getElementById('showingEnd').textContent = Math.min(start + rowsPerPage, data.length);
  document.getElementById('totalAssets').textContent = data.length.toLocaleString();

  renderPagination(totalPages);
}

function renderPagination(totalPages) {
  if (totalPages <= 1) { document.getElementById('pagination').innerHTML = ''; return; }
  let html = '';
  html += `<button class="pagination-btn" onclick="goToPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled style="opacity:0.4;"' : ''}>‹</button>`;

  let pages = [];
  if (totalPages <= 7) {
    pages = Array.from({length: totalPages}, (_, i) => i + 1);
  } else {
    pages.push(1);
    if (currentPage > 3) pages.push('...');
    for (let p = Math.max(2, currentPage - 1); p <= Math.min(totalPages - 1, currentPage + 1); p++) {
      pages.push(p);
    }
    if (currentPage < totalPages - 2) pages.push('...');
    pages.push(totalPages);
  }

  pages.forEach(p => {
    if (p === '...') html += `<span style="padding:0 4px;color:var(--text-muted);">…</span>`;
    else html += `<button class="pagination-btn ${p === currentPage ? 'active' : ''}" onclick="goToPage(${p})">${p}</button>`;
  });

  html += `<button class="pagination-btn" onclick="goToPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled style="opacity:0.4;"' : ''}>›</button>`;
  document.getElementById('pagination').innerHTML = html;
}

function goToPage(p) {
  const data = getFilteredData();
  const totalPages = Math.ceil(data.length / rowsPerPage);
  if (p < 1 || p > totalPages) return;
  currentPage = p;
  renderTable();
  window.scrollTo({ top: document.getElementById('cryptoTable').offsetTop - 120, behavior: 'smooth' });
}

