function sortTable(field) {
  if (sortField === field) {
    sortDir = sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    sortField = field;
    sortDir = 'desc';
  }
  // Update header indicators
  document.querySelectorAll('th').forEach(th => {
    th.classList.remove('sort-asc', 'sort-desc');
  });
  const ths = document.querySelectorAll('th');
  const idx = ['rank','name','price','change1h','change24h','change7d','marketCap','volume','supply','spark'].indexOf(field);
  if (idx >= 0 && ths[idx]) ths[idx].classList.add(sortDir === 'asc' ? 'sort-asc' : 'sort-desc');
  currentPage = 1;
  renderTable();
}

